-- A2 · law fields on M820-12, M820-23, M820-24
-- DWA-M-820-1 M820-12 exclusion_123_gwb_checked: visible_when (L), description, verification_quote, source_anchor
INSERT INTO fields_archive_m820_c4g SELECT f.* FROM fields f, worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-12' AND f.symbol = 'exclusion_123_gwb_checked' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = '9cd22ec43c9aaaa68db20aeaefa608ec'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_c4g a WHERE a.id = f.id);
UPDATE fields f
   SET visible_when = $m$client_organization_type != 'privat_ohne_foerderung' OR vergaberecht_freiwillig_angewendet == true$m$,
       description = $m$Bestätigt, dass die zwingenden Ausschlussgründe nach §123 GWB geprüft wurden (z. B. einschlägige Straftaten; eine Selbstreinigung kann den Ausschluss aufheben). Anhang E.1.1 (S. 58): bereits das Nichtvorlegen der geforderten Erklärungen führt zum Ausschluss. Ausgeblendet bei privatem Auftraggeber ohne Fördermittel, der das Vergaberecht nicht freiwillig anwendet (client_organization_type = privat_ohne_foerderung und vergaberecht_freiwillig_angewendet = Nein, M820-01): § 7.2 (S. 29): „An das Vergaberecht sind Auftraggeber oder private Auftraggeber, die Fördermittel erhalten, gebunden.“ Prüfungen, die diese Angabe lesen, gelten dann nicht.
[EN] Confirms the mandatory exclusion grounds under §123 GWB were checked (e.g. relevant criminal offences; self-cleaning may lift the exclusion). Anhang E.1.1 (p. 58): failing to submit the required declarations alone leads to exclusion. Hidden for a private client without public funding who does not apply procurement law voluntarily (client_organization_type = privat_ohne_foerderung and vergaberecht_freiwillig_angewendet = no, M820-01): § 7.2 (p. 29): "bound to procurement law are clients or private clients that receive funding." Checks that read this entry then do not apply.$m$,
       verification_quote = $m$In § 123 GWB sind die zwingenden Ausschlussgründe aufgeführt. Im Rahmen der Vergabe wird je nach vorliegendem Tatbestand eine Eigen- oder Fremderklärung angefordert. Bereits das Nichtvorlegen der geforderten Erklärungen [...] führt zum Ausschluss. | Grundsätzlich nicht geeignet für die Ausführung eines Auftrags ist in einem VgV-F Verfahren ein Ingenieurbüro, bei dem zwingende Ausschlussgründe gemäß § 123 GWB vorliegen. [...] so ist es zwingend auszuschließen, soweit keine Selbstreinigung erfolgte. — printed p.58, p.35 | Sichtbarkeitsregel / visibility rule (visible_when): DWA-M 820-1 § 7.2 (PDF S. 31 / gedruckt S. 29): „An das Vergaberecht sind Auftraggeber oder private Auftraggeber, die Fördermittel erhalten, gebunden.“$m$,
       source_anchor = $m$DWA-M 820-1 §7.2 Z.766 (PDF S. 31) — visible_when$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-12' AND f.symbol = 'exclusion_123_gwb_checked' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = '9cd22ec43c9aaaa68db20aeaefa608ec';
-- DWA-M-820-1 M820-12 exclusion_124_gwb_selected: visible_when (L), description, verification_quote, source_anchor
