UPDATE fields f
   SET visible_when = $m$client_organization_type != 'privat_ohne_foerderung' OR vergaberecht_freiwillig_angewendet == true$m$,
       description = $m$Register der vom Auftraggeber gewählten fakultativen Ausschlussgründe nach §124 GWB: je Grund, ob er vorab bekannt gemacht wurde. Die einzelnen §124-Gründe stehen im Gesetz, nicht im Merkblatt — hier wird nur erfasst, welche gewählt wurden. Ausgeblendet bei privatem Auftraggeber ohne Fördermittel, der das Vergaberecht nicht freiwillig anwendet (client_organization_type = privat_ohne_foerderung und vergaberecht_freiwillig_angewendet = Nein, M820-01): § 7.2 (S. 29): „An das Vergaberecht sind Auftraggeber oder private Auftraggeber, die Fördermittel erhalten, gebunden.“ Prüfungen, die diese Angabe lesen, gelten dann nicht.
[EN] Register of the optional exclusion grounds under §124 GWB chosen by the client: for each ground, whether it was disclosed in advance. The individual §124 grounds themselves are in the statute, not printed in the Merkblatt — this register records only which were chosen. Hidden for a private client without public funding who does not apply procurement law voluntarily (client_organization_type = privat_ohne_foerderung and vergaberecht_freiwillig_angewendet = no, M820-01): § 7.2 (p. 29): "bound to procurement law are clients or private clients that receive funding." Checks that read this entry then do not apply.$m$,
       verification_quote = $m$Dem Auftraggeber wird empfohlen, in den Vergabeunterlagen deutlich zu machen, ob er sich auf alle Ausschlussgründe gemäß § 124 GWB bezieht. Der Auftraggeber muss dann die Bewerber auffordern, entsprechend nachzuweisen (zuerst möglichst per Eigenerklärungen [...]), dass diese Ausschlussgründe nicht vorliegen. | Zusätzlich kann der Auftraggeber für das VgV-F-Verfahren Ausschlussgründe gemäß § 124 GWB angeben. Es wird dringend empfohlen, die ausgewählten Kriterien aus Gründen der Transparenz vorab bekannt zu machen. — printed p.58, p.35 | Sichtbarkeitsregel / visibility rule (visible_when): DWA-M 820-1 § 7.2 (PDF S. 31 / gedruckt S. 29): „An das Vergaberecht sind Auftraggeber oder private Auftraggeber, die Fördermittel erhalten, gebunden.“$m$,
       source_anchor = $m$DWA-M 820-1 §7.2 Z.766 (PDF S. 31) — visible_when$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-12' AND f.symbol = 'exclusion_124_gwb_selected' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = '5dcf2c69c3b954215c12ee2c019f4b13';
