UPDATE fields f
   SET visible_when = $m$procurement_procedure != 'direktvergabe'$m$,
       description = $m$Kurzbeschreibung der Dokumentationsstruktur für Bewerbungsbedingungen, Eignungskriterien und Leistungsbeschreibung, wie sie vor der Bekanntmachung feststehen muss (§8.10.2.2, Anhang E.1). Bei Direktvergabe ausgeblendet (procurement_procedure = direktvergabe, M820-10): § 8.8 (S. 36): „Eine Direktvergabe ist eine Vergabe, bei der Verhandlungen mit nur einem Unternehmen geführt werden.“ Ohne Wettbewerb zwischen Bewerbern oder Bietern hat diese Angabe keinen Gegenstand. Zu dokumentieren bleiben die Gründe der Direktvergabe (procedure_rationale, M820-10) – § 8.8 (S. 37): „Die Gründe für eine Direktvergabe sind in jedem Fall zu dokumentieren, entweder im Vergabevermerk oder an anderer Stelle.“ Die Leistungsbeschreibung bleibt (leistungsbeschreibung_complete, dieses Blatt) – § 8.2 (S. 32): „Der Auftraggeber hat bei allen Vergabeverfahren eine Aufgabenbeschreibung zu erstellen.“
[EN] Short description of the documentation structure for application conditions, eligibility criteria and service description, which must be settled before the publication notice (§8.10.2.2, Anhang E.1). Hidden for a direct award (procurement_procedure = direktvergabe, M820-10): § 8.8 (p. 36): "a direct award is an award in which negotiations are conducted with only one company." Without competition between applicants or bidders this entry has no subject. The reasons for the direct award remain to be documented (procedure_rationale, M820-10) – § 8.8 (p. 37): "the reasons for a direct award are to be documented in every case, either in the award memo or elsewhere." The service description remains (leistungsbeschreibung_complete, this sheet) – § 8.2 (p. 32): "the client must draw up a task description in all award procedures."$m$,
       verification_quote = $m$Gemäß § 41 Abs. 1 VgV hat der Auftraggeber bereits mit Bekanntmachung, die Vergabeunterlagen unentgeltlich, uneingeschränkt, vollständig und direkt zur Verfügung zu stellen. § 29 Abs. 1 VgV definiert, aus welchen Bestandteilen sich die Vergabeunterlagen in der Regel zusammensetzen. — printed p.32 | Sichtbarkeitsregel / visibility rule (visible_when): DWA-M 820-1 § 8.8 (PDF S. 38 / gedruckt S. 36): „Eine Direktvergabe ist eine Vergabe, bei der Verhandlungen mit nur einem Unternehmen geführt werden.“$m$,
       source_anchor = $m$DWA-M 820-1 §8.8 Z.908 (PDF S. 38) — visible_when$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-15' AND f.symbol = 'documentation_structure' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = '3d987952e30cb85d3b4dab0ef63f016e';
