UPDATE fields f
   SET visible_when = $m$procurement_procedure != 'direktvergabe'$m$,
       description = $m$Startdatum des Vergabeverfahrens (Veröffentlichung); Teil der Terminpläne nach §4.3. Bei Direktvergabe ausgeblendet (procurement_procedure = direktvergabe, M820-10): § 8.8 (S. 36): „Eine Direktvergabe ist eine Vergabe, bei der Verhandlungen mit nur einem Unternehmen geführt werden.“ Ohne Wettbewerb zwischen Bewerbern oder Bietern hat diese Angabe keinen Gegenstand. Zu dokumentieren bleiben die Gründe der Direktvergabe (procedure_rationale, M820-10) – § 8.8 (S. 37): „Die Gründe für eine Direktvergabe sind in jedem Fall zu dokumentieren, entweder im Vergabevermerk oder an anderer Stelle.“
[EN] Start date of the procurement procedure (publication); part of the schedules under §4.3. Hidden for a direct award (procurement_procedure = direktvergabe, M820-10): § 8.8 (p. 36): "a direct award is an award in which negotiations are conducted with only one company." Without competition between applicants or bidders this entry has no subject. The reasons for the direct award remain to be documented (procedure_rationale, M820-10) – § 8.8 (p. 37): "the reasons for a direct award are to be documented in every case, either in the award memo or elsewhere."$m$,
       verification_quote = $m$Sichtbarkeitsregel / visibility rule (visible_when): DWA-M 820-1 § 8.8 (PDF S. 38 / gedruckt S. 36): „Eine Direktvergabe ist eine Vergabe, bei der Verhandlungen mit nur einem Unternehmen geführt werden.“$m$,
       source_anchor = $m$DWA-M 820-1 §8.8 Z.908 (PDF S. 38) — visible_when$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-17' AND f.symbol = 'date_procurement_start' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = 'b89c23a93d3ecb03b95cf2461fa098fc';
