   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = '6fccd64e264121e8f2fb040943c5e1c3'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_c4g a WHERE a.id = f.id);
UPDATE fields f
   SET description = $m$Nur bei privatem Auftraggeber ohne Fördermittel relevant: nach § 7.2 (S. 29): „An das Vergaberecht sind Auftraggeber oder private Auftraggeber, die Fördermittel erhalten, gebunden.“ Die Anwendung des Merkblatts steht frei (S. 10). Ja = alle Vergabeprüfungen gelten wie bei einem öffentlichen Auftraggeber. Nein = ausgeblendet werden die Schwellenwertbestimmung (ganzes Blatt M820-09), die Ausschlussgründe nach §123/§124 GWB (M820-12), das Veröffentlichungsdatum publication_date („Veröffentlichungsdatum“ der TED-Bekanntmachung, M820-17), Informationsschreiben, elektronische Übermittlung, Wartefrist und §135-GWB-Risiko (M820-23) sowie Vergabevermerk und Vergabeakte (M820-24, § 8.3 (S. 32): „Bei einer Direktvergabe oder einem Suchverfahren ist der Auftraggeber zwar nicht dazu verpflichtet, sollte es aber bereits aus haushaltsrechtlichen Gründen oder bei dem Erhalt von Fördermitteln zwecks Dokumentation tun.“); die Prüfungen REQ-07, REQ-08, REQ-10, REQ-14, REQ-19, REQ-20, REQ-21, REQ-22, REQ-23, REQ-23-2 und REQ-26 gelten nicht. Sichtbar bleiben das Vergabeverfahren und seine Begründung (M820-10), die Leistungsbeschreibung (M820-15), der Vergabestart date_procurement_start („Datum Vergabestart“, M820-17 – nur bei Direktvergabe ausgeblendet), die Angaben zu Verhandlung, Vertrag und Versicherung (M820-20 bis M820-22) sowie Auftragsdatum / Auftragnehmer (award_date, contractor_auftragnehmer, M820-23); welche Wettbewerbsangaben zusätzlich entfallen, hängt vom gewählten Verfahren ab (M820-10).
[EN] Relevant only for a private client without public funding: per § 7.2 (p. 29): "bound to procurement law are clients or private clients that receive funding." Applying the Merkblatt is voluntary (p. 10). Yes = every procurement check applies as for a public client. No = hidden are the threshold determination (whole sheet M820-09), the exclusion grounds under §123/§124 GWB (M820-12), the publication date publication_date ("Veröffentlichungsdatum" of the TED notice, M820-17), information letters, electronic transmission, standstill period and §135 GWB risk (M820-23), and the award memo and award file (M820-24, § 8.3 (p. 32): "in a direct award or a search procedure the client is admittedly not obliged to, but should do it already for reasons of budget law or when receiving funding, for the purpose of documentation."); the checks REQ-07, REQ-08, REQ-10, REQ-14, REQ-19, REQ-20, REQ-21, REQ-22, REQ-23, REQ-23-2 and REQ-26 do not apply. What stays visible: the procedure and its justification (M820-10), the service description (M820-15), the procurement start date_procurement_start ("Datum Vergabestart", M820-17 – hidden only for a direct award), the negotiation, contract and insurance entries (M820-20 to M820-22) and the award date / contractor (award_date, contractor_auftragnehmer, M820-23); which competition entries are hidden in addition depends on the chosen procedure (M820-10).$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND f.symbol = 'vergaberecht_freiwillig_angewendet' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = '6fccd64e264121e8f2fb040943c5e1c3';
