 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND f.symbol = 'procurement_procedure' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = 'cac88579d920c3b0c3214104010a9766'
   AND NOT EXISTS (SELECT 1 FROM fields_archive_m820_c4g a WHERE a.id = f.id);
UPDATE fields f
   SET description = $m$Gewähltes Vergabeverfahren: VgV-F-Verfahren (oberschwellig, §8.6), Suchverfahren (§8.9) oder Direktvergabe (§8.8; unterschwellig, ausnahmsweise auch oberschwellig) oder Planungswettbewerb (§8.11, Ausnahmefall). Die Wahl folgt aus dem Schwellenwert-Status auf M820-09. Direktvergabe blendet die Wettbewerbsangaben auf M820-11, M820-13 bis M820-19 aus (Leistungswettbewerb und Mindesteignung samt Prüfdatum, Eignungskriterien samt geforderter Deckungssummen, Zuschlagskriterien, Bewerbungsbedingungen und Dokumentationsstruktur, Bewertungskommission, Bekanntmachung und Vergabestart, Bewerber- und Angebotswertung) – § 8.8 (S. 36): „Eine Direktvergabe ist eine Vergabe, bei der Verhandlungen mit nur einem Unternehmen geführt werden.“ Die Prüfungen REQ-12 (M820-13), REQ-15 und REQ-16 (M820-14) und REQ-17 (M820-11) gelten dann nicht. Es bleiben: die Begründung (procedure_rationale, dieses Blatt; § 8.8, S. 37: „Die Gründe für eine Direktvergabe sind in jedem Fall zu dokumentieren …“), die Aufgabenbeschreibung (§ 8.2 (S. 32): „Der Auftraggeber hat bei allen Vergabeverfahren eine Aufgabenbeschreibung zu erstellen.“ – Leistungsbeschreibung auf M820-15), das Verhandlungsprotokoll M820-20 (verhandelt wird auch bei Direktvergabe), die Vertragscheckliste M820-21, Versicherung und Haftung M820-22 und der Dokumentationsabschluss M820-24 (§ 8.3, S. 32: „zwar nicht dazu verpflichtet, sollte es aber …“ – Warnung REQ-23-2). Privater Auftraggeber ohne Fördermittel, der das Vergaberecht nicht freiwillig anwendet (vergaberecht_freiwillig_angewendet = Nein, M820-01): zusätzlich ausgeblendet sind M820-09, die GWB-Angaben auf M820-12 und M820-23 und der Dokumentationsabschluss M820-24 – § 7.2 (S. 29): „An das Vergaberecht sind Auftraggeber oder private Auftraggeber, die Fördermittel erhalten, gebunden.“ Suchverfahren und Planungswettbewerb: alle Wettbewerbsangaben bleiben.
[EN] Chosen procurement procedure: VgV-F procedure (above threshold, §8.6), search procedure (§8.9) or direct award (§8.8; below threshold, exceptionally also above), or design competition (§8.11, an exception). The choice follows from the threshold status on M820-09. A direct award hides the competition entries on M820-11 and M820-13 to M820-19 (performance competition and minimum eligibility with its check date, eligibility criteria with the required insurance sums, award criteria, application conditions and documentation structure, evaluation commission, notice and procurement start, applicant and offer evaluation) – § 8.8 (p. 36): "a direct award is an award in which negotiations are conducted with only one company." The checks REQ-12 (M820-13), REQ-15 and REQ-16 (M820-14) and REQ-17 (M820-11) then do not apply. What remains: the justification (procedure_rationale, this sheet; § 8.8, p. 37: "the reasons for a direct award are to be documented in every case …"), the task description (§ 8.2 (p. 32): "the client must draw up a task description in all award procedures." – service description on M820-15), the negotiation record M820-20 (negotiations also take place in a direct award), the contract checklist M820-21, insurance and liability M820-22 and the documentation close-out M820-24 (§ 8.3, p. 32: "not obliged to, but should …" – warning REQ-23-2). A private client without public funding who does not apply procurement law voluntarily (vergaberecht_freiwillig_angewendet = no, M820-01): hidden in addition are M820-09, the GWB entries on M820-12 and M820-23 and the documentation close-out M820-24 – § 7.2 (p. 29): "bound to procurement law are clients or private clients that receive funding." Search procedure and design competition: all competition entries remain.$m$
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND f.symbol = 'procurement_procedure' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = 'cac88579d920c3b0c3214104010a9766';

